      { q: { id: "Hadits kartu (bithaqah) menunjukkan bahwa yang memberatkan timbangan adalah…", ar: "حديث البطاقة يدل على أن الذي يثقل الميزان…" }, o: [{ id: "Banyaknya catatan", ar: "كثرة السجلات" }, { id: "Panjangnya kartu", ar: "طول البطاقة" }, { id: "Syahadat yang ikhlas dari hati", ar: "الشهادة الخالصة من القلب" }, { id: "Kekayaan seseorang", ar: "غنى الإنسان" }], j: 2, b: { id: "Catatan keburukan terangkat dan kartu syahadat berat: “tak ada yang berat bersama nama Allah.”", ar: "«فَلَا يَثْقُلُ مَعَ اسْمِ اللَّهِ شَيْءٌ»." } }
