      { t: { id: "'Isa عليه السلام wafat disalib sebagaimana klaim kaum Yahudi dan Nasrani.", ar: "عيسى عليه السلام مات مصلوبًا." }, j: false, b: { id: "{وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ} — yang disalib adalah orang yang diserupakan dengannya.", ar: "ما قتلوه وما صلبوه ولكن شُبّه لهم." } },
      { t: { id: "Setelah turun, 'Isa mematahkan salib, membunuh babi, dan menghapus jizyah.", ar: "عيسى ينزل فيكسر الصليب ويقتل الخنزير ويضع الجزية." }, j: true },
      { t: { id: "Setelah matahari terbit dari barat, taubat dan iman yang baru tetap diterima.", ar: "بعد طلوع الشمس من مغربها تقبل التوبة." }, j: false, b: { id: "Itulah saat {لَا يَنفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِن قَبْلُ}; taubat tidak lagi diterima.", ar: "لا ينفع نفسًا إيمانها لم تكن آمنت من قبل." } },
      { t: { id: "Menurut dosen, Al-Qurthubi menolak pendapat bahwa Dabbah adalah manusia yang berdebat dengan ahli bid'ah.", ar: "رد القرطبي القول بأن الدابة إنسان يناظر أهل البدع." }, j: true },
      { t: { id: "Hawd Nabi ﷺ dan sungai Al-Kautsar adalah dua nama untuk satu hal menurut pendapat rajih yang dosen sebutkan.", ar: "الحوض هو الكوثر عند الراجح." }, j: false, b: { id: "Pendapat rajih: Al-Kautsar sungai di surga, berbeda dari hawd.", ar: "الراجح أن الكوثر غير الحوض." } },
      { t: { id: "Syafaat hanya terjadi dengan izin Allah dan ridha-Nya terhadap orang yang diberi syafaat.", ar: "الشفاعة لا تكون إلا بإذن الله ورضاه عن المشفوع له." }, j: true }
